-- Read-only acceptance for v0.14.0.290_supabase_member_rls_initplan_v2
BEGIN READ ONLY;
SELECT tablename,policyname,cmd,roles,qual,with_check FROM pg_policies WHERE schemaname='public' AND (tablename,policyname) IN (('decision_journal','read own decision journal'),('forum_topics','update own unlocked forum topics'),('forum_posts','update own forum posts'),('decision_journal','insert own decision journal'),('decision_journal','update own decision journal'),('decision_journal','delete own decision journal'),('forum_topics','read published forum topics'),('forum_topics','create own forum topics'),('forum_posts','read published forum posts'),('forum_posts','create own forum posts'),('trade_plan_snapshots','read own plan snapshots'),('journal_reviews','read own journal reviews'),('journal_reviews','update own journal reviews'),('site_orders','read own site orders'),('site_order_items','read own site order items'),('site_subscriptions','read own subscriptions'),('user_tool_passes','read own tool passes'),('checkout_intents','users read own checkout intents'),('replay_practice_sessions_v135','replay learner reads own practice'),('commons_topics','members read commons topics'),('commons_posts','members read commons posts'),('commons_bookmarks','users read own commons bookmarks'),('commons_topic_subscriptions','users read own commons subscriptions')) ORDER BY tablename,policyname;
SELECT count(*) as protected_tables_without_rls FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relrowsecurity;
COMMIT;
